const store = $getWorkflowStaticData('global');
const lastTimestamp = store.lastRt21Run || '2000-01-01T00:00:00Z';
const runDate = new Date().toISOString();
store.lastRt21Run = runDate;
store.createdThisRun = {};
return [{ json: { lastTimestamp, runDate } }];

const rows = $input.first().json.value || [];
const store = $getWorkflowStaticData('global');
const shipToMap = {};
for (const row of rows) {
  const custNo = String(row.HFSCustomerNo || '').trim();
  if (custNo && !shipToMap[custNo]) {
    shipToMap[custNo] = { address: row.Address || null, address2: row.Address_2 || null, city: row.City || null, zip: row.Post_Code || null };
  }
}
store.shipToMap = shipToMap;
return [{ json: { shipToLoaded: Object.keys(shipToMap).length } }];

const customers = $input.first().json.value || [];
const store = $getWorkflowStaticData('global');
const customerMap = {};
for (const c of customers) {
  if (c.number) customerMap[String(c.number)] = c;
}
store.customerMap = customerMap;
return [{ json: { bcCustomerCount: customers.length } }];

const store = $getWorkflowStaticData('global');
store.hsCompanies = [];
store.hsCursor = null;
return [{ json: { initialized: true } }];

const store = $getWorkflowStaticData('global');
const payload = {
  filterGroups: [{
    filters: [
      { propertyName: 'relationship',        operator: 'EQ',             value: 'Customer' },
      { propertyName: 'division_multiselect', operator: 'CONTAINS_TOKEN', value: "Engelman's Bakery" },
      { propertyName: 'erp_account_number',   operator: 'HAS_PROPERTY' },
      { propertyName: 'route',                operator: 'EQ',             value: 'Route 21 - Distribution' }
    ]
  }],
  properties: ['hs_object_id', 'erp_account_number', 'name'],
  limit: 200
};
if (store.hsCursor) payload.after = store.hsCursor;
return [{ json: payload }];

const response = $input.first().json;
const results = response.results || [];
const store = $getWorkflowStaticData('global');
if (!store.hsCompanies) store.hsCompanies = [];
store.hsCompanies.push(...results);
const nextCursor = response.paging?.next?.after;
store.hsCursor = (nextCursor && results.length > 0) ? nextCursor : null;
const hasMore = store.hsCursor !== null ? 1 : 0;
return [{ json: { fetched: store.hsCompanies.length, thisPage: results.length, hasMore } }];

const store = $getWorkflowStaticData('global');
const companies = store.hsCompanies || [];
if (companies.length === 0) return [{ json: { skipped: true, count: 0 } }];
return companies.map(c => ({ json: c }));

const store = $getWorkflowStaticData('global');
const totalProcessed = (store.hsCompanies || []).length;
store.hsCompanies = [];
store.hsCursor = null;
store.customerMap = {};
store.currentBatch = [];
return [{ json: { message: 'Route 21 Companies sync complete', totalProcessed } }];

const batchItems = $input.all();
const store = $getWorkflowStaticData('global');
store.currentBatch = batchItems.map(i => i.json);
const odataFilter = batchItems
  .map(item => {
    const erpNum = item.json.properties?.erp_account_number || item.json.erp_account_number || '';
    return `No eq '${String(erpNum).replace(/'/g, "''")}'`;
  })
  .join(' or ');
return [{ json: { odataFilter } }];

const odataRows = $input.first().json.value || [];
const store = $getWorkflowStaticData('global');
const currentBatch = store.currentBatch || [];
const customerMap  = store.customerMap  || {};
const shipToMap    = store.shipToMap    || {};

const routeMap = {
  'RT 1':  'Route 1',  'RT 2':  'Route 2',  'RT 3':  'Route 3',
  'RT 4':  'Route 4',  'RT 5':  'Route 5',  'RT 6':  'Route 6',
  'RT 7':  'Route 7',  'RT 8':  'Route 8',  'RT 9':  'Route 9',
  'RT 10': 'Route 10', 'RT 11': 'Route 11', 'RT 12': 'Route 12',
  'RT 13': 'Route 13', 'RT 15': '15 - Greenville',
  'RT 16': 'Route 16 - Boxed', 'RT 20': 'Route 20 - Supervisor',
  'RT 21': 'Route 21 - Distribution'
};
const paymentMethodMap = {
  'ACH': 'ACH Upon Due Date', 'CCA': 'Credit Card Auto',
  'CCW': 'Credit Card Weekly', 'Check': 'Check',
  'COD': 'Cash on Delivery', 'CCM': 'Credit Card Monthly',
  'CCP': 'Credit Card Payment Plan'
};
const salespersonMap = {
  'CUDICK': '90537115', 'DHALL': '58718266',
  'LLONG': '53148531', 'GCOPLIN': '89639254', 'HWEST': '53148526'
};

function calendarToDays(code) {
  if (!code) return null;
  const days = [];
  let i = 0;
  while (i < code.length) {
    if (code.slice(i, i+2) === 'TH') { days.push('Thursday'); i += 2; }
    else if (code[i] === 'M') { days.push('Monday'); i++; }
    else if (code[i] === 'T') { days.push('Tuesday'); i++; }
    else if (code[i] === 'W') { days.push('Wednesday'); i++; }
    else if (code[i] === 'F') { days.push('Friday'); i++; }
    else if (code[i] === 'S') { days.push('Saturday'); i++; }
    else i++;
  }
  const order = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
  return order.filter(d => days.includes(d)).join(';') || null;
}

const odataMap = {};
for (const r of odataRows) odataMap[String(r.No)] = r;

const toUpdate = [];
for (const hsCompany of currentBatch) {
  const erpNum = String(hsCompany.properties?.erp_account_number || '').trim();
  if (!erpNum) continue;

  const odata = odataMap[erpNum] || {};
  const c     = customerMap[erpNum];
  const ship  = shipToMap[erpNum] || {};
  const raw   = {};

  if (odata.Balance_LCY     != null) raw.balance     = odata.Balance_LCY;
  if (odata.Balance_Due_LCY != null) raw.balance_due = odata.Balance_Due_LCY;
  const rawRoute = odata.Shipping_Agent_Code ? String(odata.Shipping_Agent_Code).trim() : null;
  if (rawRoute) { const r = routeMap[rawRoute]; if (r) raw.route = r; }
  const days = calendarToDays(odata.Base_Calendar_Code);
  if (days) raw.days_of_delivery = days;

  if (ship.address)  raw.address  = ship.address;
  if (ship.address2) raw.address2 = ship.address2;
  if (ship.city)     raw.city     = ship.city;
  if (ship.zip)      raw.zip      = ship.zip;

  if (c) {
    const bcBlocked = c.blocked && c.blocked.trim() && c.blocked.trim() !== '_x0020_';
    if (c.displayName)  raw.name  = c.displayName;
    if (c.addressLine1) raw.billing_street_address   = c.addressLine1;
    if (c.addressLine2) raw.billing_street_address_2 = c.addressLine2;
    if (c.city)         raw.billing_city  = c.city;
    if (c.state)        raw.billing_state = c.state;
    const zip = c.postalCode != null ? String(c.postalCode).trim() : '';
    if (zip) raw.billing_zip_code = zip;
    raw.payment_terms_code  = c.paymentTerm?.code || null;
    const pmCode = c.paymentMethod?.code;
    raw.payment_method_code = (pmCode && paymentMethodMap[pmCode]) ? paymentMethodMap[pmCode] : null;
    if (c.creditLimit != null) raw.credit_limit = c.creditLimit;
    raw.blocked = bcBlocked ? 'Blocked' : '';
    const spCode = c.salespersonCode ? String(c.salespersonCode).trim() : null;
    if (spCode && salespersonMap[spCode]) raw.hubspot_owner_id = salespersonMap[spCode];
  }

  const props = {};
  for (const [k, v] of Object.entries(raw)) {
    if (v !== null && v !== undefined && v !== '') props[k] = v;
  }
  if (c && 'blocked' in raw)             props.blocked             = raw.blocked;
  if (c && 'payment_terms_code' in raw)  props.payment_terms_code  = raw.payment_terms_code;
  if (c && 'payment_method_code' in raw) props.payment_method_code = raw.payment_method_code;

  if (Object.keys(props).length > 0) {
    toUpdate.push({ id: hsCompany.id, properties: props });
  }
}

return [{ json: { toUpdate, updateCount: toUpdate.length } }];
